/**
 * LIA → Elixir emitter.
 */
import { parseLia } from './compiler.mjs';
import { parseParamList, safeEmitId, isJsRuntimeOnly } from './emit_shared.mjs';

export function emitElixir(liaText, opts = {}) {
  const prog = parseLia(liaText);
  const modName = opts.moduleName || 'LinEmit';
  const parts = [
    '# generated by lia multi-emit → elixir',
    `defmodule ${modName} do`,
    '  def _lia_typeof(nil), do: "object"',
    '  def _lia_typeof(x) when is_binary(x), do: "string"',
    '  def _lia_typeof(x) when is_number(x), do: "number"',
    '  def _lia_typeof(x) when is_boolean(x), do: "boolean"',
    '  def _lia_typeof(_), do: "object"',
    '',
  ];

  for (const fn of prog.fns) {
    const { names: params } = parseParamList(fn.params);
    const exName = safeEmitId(fn.name).replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase();
    if (opts.stubRuntime !== false || isJsRuntimeOnly(fn.body, fn.name)) {
      parts.push(`  def ${exName}(), do: raise("JS-runtime-only")`);
      continue;
    }
    const paramList = params.map((p) => `_${p}`).join(', ');
    parts.push(`  def ${exName}(${paramList}) do`);
    parts.push('    nil');
    parts.push('  end');
  }

  parts.push('end');
  return { code: parts.join('\n'), lang: 'elixir' };
}
